ClearAll[x,a,d,nL,nR,m,k,t,pL];
p=pL+d*nL*x+d*(3*m-2*nL-nR)*x^2+d*(-2*m+nL+nR)*x^3;
n=Expand[D[p,x]/d];
susc=Expand[D[n,x]/d];
causal=Expand[(a+d*x)*susc-n];
phi=(Exp[k*x]-1)/(Exp[k]-1);
J=Integrate[(a+d*x)*phi,{x,0,t},Assumptions->{Element[{a,d,k,t},Reals],a>0,d>0,k!=0,0<=t<=1}];
checks={
 FullSimplify[n-(nL+(6*m-4*nL-2*nR)*x+(3*nL+3*nR-6*m)*x^2)]===0,
 FullSimplify[D[causal,x]-(a+d*x)*D[n,{x,2}]/d]===0,
 FullSimplify[(causal/.x->0)-(a*(6*m-4*nL-2*nR)/d-nL)]===0,
 FullSimplify[(causal/.x->1)-((a+d)*(-6*m+2*nL+4*nR)/d-nR)]===0
};
<|"density"->n,"susceptibility"->susc,"causal_polynomial"->causal,"symbolic_zero_checks"->checks,"exponential_integral"->J,"phi_zero_parameter_limit"->Limit[phi,k->0],"integral_zero_parameter_limit"->Limit[J,k->0]|>
